PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY,email TEXT UNIQUE NOT NULL,password_hash TEXT NOT NULL,full_name TEXT NOT NULL,role TEXT NOT NULL CHECK(role IN('client','courier','restaurant','supermarket','admin')),business_name TEXT,phone TEXT,address TEXT NOT NULL DEFAULT '',avatar_url TEXT,active INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS sessions(token TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,expires_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS products(id TEXT PRIMARY KEY,owner_id TEXT NOT NULL REFERENCES users(id),name TEXT NOT NULL,description TEXT,kind TEXT NOT NULL CHECK(kind IN('meal','grocery')),category TEXT NOT NULL DEFAULT 'Autre',retail_price INTEGER NOT NULL CHECK(retail_price>=0),wholesale_price INTEGER NOT NULL CHECK(wholesale_price>=0 AND wholesale_price<=retail_price),emoji TEXT NOT NULL DEFAULT '🍽️',media_url TEXT,media_type TEXT NOT NULL DEFAULT 'image' CHECK(media_type IN('image','video')),ingredients TEXT NOT NULL DEFAULT '',allergens TEXT NOT NULL DEFAULT '',preparation_minutes INTEGER NOT NULL DEFAULT 15,calories INTEGER,active INTEGER NOT NULL DEFAULT 1,approval_status TEXT NOT NULL DEFAULT 'approved' CHECK(approval_status IN('pending','approved','rejected')),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS orders(id TEXT PRIMARY KEY,code TEXT UNIQUE NOT NULL,customer_id TEXT NOT NULL REFERENCES users(id),merchant_id TEXT NOT NULL REFERENCES users(id),courier_id TEXT REFERENCES users(id),status TEXT NOT NULL DEFAULT 'placed' CHECK(status IN('placed','courier_validated','merchant_accepted','preparing','ready','picked_up','delivered','cancelled')),food_total INTEGER NOT NULL,delivery_fee INTEGER NOT NULL DEFAULT 200,commission_percent INTEGER NOT NULL DEFAULT 10,commission_amount INTEGER NOT NULL DEFAULT 0,total INTEGER GENERATED ALWAYS AS(food_total+delivery_fee) STORED,address TEXT NOT NULL,customer_note TEXT NOT NULL DEFAULT '',payment_method TEXT NOT NULL DEFAULT 'cash',payment_status TEXT NOT NULL DEFAULT 'pending' CHECK(payment_status IN('pending','paid','refunded')),client_confirmed_at TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS order_items(id TEXT PRIMARY KEY,order_id TEXT NOT NULL REFERENCES orders(id) ON DELETE CASCADE,product_id TEXT NOT NULL REFERENCES products(id),quantity INTEGER NOT NULL CHECK(quantity>0),retail_unit_price INTEGER NOT NULL,wholesale_unit_price INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS wallet_entries(id TEXT PRIMARY KEY,owner_id TEXT NOT NULL REFERENCES users(id),order_id TEXT REFERENCES orders(id),entry_type TEXT NOT NULL,amount INTEGER NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS withdrawal_requests(id TEXT PRIMARY KEY,owner_id TEXT NOT NULL REFERENCES users(id),amount INTEGER NOT NULL CHECK(amount>0),status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN('pending','approved','rejected','paid')),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS categories(id TEXT PRIMARY KEY,name TEXT NOT NULL,kind TEXT NOT NULL CHECK(kind IN('meal','grocery')),active INTEGER NOT NULL DEFAULT 1,sort_order INTEGER NOT NULL DEFAULT 0,created_by TEXT REFERENCES users(id),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(name,kind));
CREATE TABLE IF NOT EXISTS notifications(id TEXT PRIMARY KEY,recipient_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,title TEXT NOT NULL,message TEXT NOT NULL,type TEXT NOT NULL DEFAULT 'info',order_id TEXT REFERENCES orders(id) ON DELETE CASCADE,event_key TEXT NOT NULL,is_read INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(recipient_id,event_key));
CREATE UNIQUE INDEX IF NOT EXISTS wallet_once ON wallet_entries(order_id,owner_id,entry_type);
CREATE INDEX IF NOT EXISTS orders_customer_idx ON orders(customer_id,created_at);
CREATE INDEX IF NOT EXISTS orders_merchant_idx ON orders(merchant_id,status,created_at);
CREATE INDEX IF NOT EXISTS orders_courier_idx ON orders(courier_id,status,created_at);
CREATE INDEX IF NOT EXISTS notifications_recipient_idx ON notifications(recipient_id,is_read,created_at);
CREATE TABLE IF NOT EXISTS platform_settings(id INTEGER PRIMARY KEY CHECK(id=1),commission_percent INTEGER NOT NULL DEFAULT 10 CHECK(commission_percent BETWEEN 0 AND 100),delivery_fee INTEGER NOT NULL DEFAULT 200 CHECK(delivery_fee>=0));
INSERT OR IGNORE INTO platform_settings(id,commission_percent,delivery_fee) VALUES(1,10,200);
